import pytest
from hypothesis import given, assume
import hypothesis.strategies as st
from solution import move_one_ball


def ref_drops(arr):
    """Obviously-correct reference model from spec: sorted or one drop + wrap."""
    if len(arr) == 0:
        return True
    s = sorted(arr)
    if list(arr) == s:
        return True
    drops = sum(1 for i in range(len(arr) - 1) if arr[i] > arr[i + 1])
    if drops != 1:
        return False
    return arr[0] > arr[-1]


def right_shift(arr, k):
    n = len(arr)
    if n == 0:
        return list(arr)
    k = k % n
    return arr[n - k:] + arr[:n - k] if k else list(arr)


def test_example_sorted_rotation_true():
    assert move_one_ball([3, 4, 5, 1, 2]) is True


def test_example_not_rotation_false():
    assert move_one_ball([3, 5, 4, 1, 2]) is False


def test_empty_returns_true():
    assert move_one_ball([]) is True


def test_single_element_always_true():
    assert move_one_ball([7]) is True
    assert move_one_ball([-100]) is True


@given(st.lists(st.integers(min_value=-50, max_value=50), unique=True, max_size=8))
def test_property_already_sorted_always_true(arr):
    s = sorted(arr)
    assert move_one_ball(list(s)) is True


@given(st.lists(st.integers(min_value=-100, max_value=100), unique=True, min_size=0, max_size=10))
def test_property_equivalence_to_drops_reference(arr):
    assert move_one_ball(list(arr)) == ref_drops(list(arr))


@given(st.lists(st.integers(min_value=-100, max_value=100), unique=True, min_size=0, max_size=10))
def test_property_rotation_invariance(arr):
    # Any rotation has the same set of rotations, so answer is invariant.
    n = len(arr)
    if n <= 1:
        assume(True)
        assert move_one_ball(list(arr)) is True
        return
    k = 1
    shifted = arr[-k:] + arr[:-k]
    assert move_one_ball(list(arr)) == move_one_ball(list(shifted))
    # full cycle returns to start
    assert move_one_ball(right_shift(list(arr), n)) == move_one_ball(list(arr))


@given(st.lists(st.integers(min_value=-200, max_value=200), unique=True, min_size=1, max_size=10),
       st.integers(min_value=0, max_value=20))
def test_property_rotation_of_sorted_always_true(arr, k):
    s = sorted(arr)
    n = len(s)
    r = right_shift(list(s), k % n if n else 0)
    assert move_one_ball(r) is True


@given(st.integers(min_value=-100, max_value=100), st.integers(min_value=-100, max_value=100))
def test_property_two_elements_always_true(a, b):
    assume(a != b)
    assert move_one_ball([a, b]) is True
    assert move_one_ball([b, a]) is True


@given(st.lists(st.integers(min_value=-100, max_value=100), unique=True, min_size=3, max_size=10))
def test_property_reverse_sorted_is_false(arr):
    s = sorted(arr)
    rev = list(reversed(s))
    # strictly decreasing with n>=3 has n-1 drops > 1, cannot be a rotation
    assert move_one_ball(rev) is False


@given(st.lists(st.integers(min_value=-50, max_value=50), unique=True, min_size=3, max_size=8))
def test_property_returns_bool(arr):
    res = move_one_ball(list(arr))
    assert res is True or res is False
    assert type(res) is bool
